type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE';
type Handler = (req: Request) => Promise<Response>;

const routes: Record<HttpMethod, Handler> = {
  GET: async (req) => new Response('ok'),
  POST: async (req) => new Response('created'),
  PUT: async (req) => new Response('updated'),
  DELETE: async (req) => new Response('deleted'),
};

type Status = 'pending' | 'active' | 'archived' | 'deleted';

type VisibleStatus = Exclude<Status, 'deleted'>;
type TerminalStatus = Extract<Status, 'archived' | 'deleted'>;

